  'home.fitmentCalcDesc': { en: 'Compare your existing wheel and tyre setup with a new configuration. Check poke, inset, speedo error, ride height and strut clearance before you buy.', nl: 'Vergelijk uw huidige velg- en bandopstelling met een nieuwe configuratie. Controleer poke, inset, snelheidsmeterafwijking, rijhoogte en veerpootspeling voordat u koopt.', de: 'Vergleichen Sie Ihre bestehende Felgen- und Reifenkonfiguration mit einer neuen. Prüfen Sie Poke, Inset, Tacho-Abweichung, Fahrhöhe und Federbeindurchlass vor dem Kauf.', es: 'Compare su configuración actual de llantas y neumáticos con una nueva. Verifique poke, inset, error del velocímetro, altura de rodaje y espacio libre del amortiguador antes de comprar.', fr: 'Comparez votre configuration actuelle de jantes et pneus avec une nouvelle. Vérifiez le poke, l\'inset, l\'erreur du compteur, la hauteur de caisse et le dégagement de jambe de force avant d\'acheter.', pl: 'Porównaj obecny zestaw felg i opon z nową konfiguracją. Sprawdź poke, inset, błąd prędkościomierza, wysokość jazdy i luz kolumny zawieszenia przed zakupem.' },
  'home.openFitmentCalc': { en: 'Open Fitment Calc', nl: 'Fitment Calculator openen', de: 'Einpress-Rechner öffnen', es: 'Abrir Calculadora de Montaje', fr: 'Ouvrir le Calculateur de Montage', pl: 'Otwórz Kalkulator Dopasowania' },
  'home.specCalcTitle': { en: '3-Piece Rebuild Spec Calculator', nl: '3-Delig Rebuild Spec Calculator', de: '3-Teiler Rebuild Spec-Rechner', es: 'Calculadora Spec de Reconstrucción 3 Piezas', fr: 'Calculateur Spec de Reconstruction 3 Pièces', pl: 'Kalkulator Spec Odbudowy 3-częściowej' },
  'home.specCalcDesc': { en: 'Configure your 3-piece wheel widening specs. Calculate inner barrel and outer lip sizes, new ET offset, and save your configurations for later.', nl: 'Configureer uw 3-delige velg verbredingsspecificaties. Bereken inner barrel en outer lip maten, nieuwe ET offset, en sla uw configuraties op.', de: 'Konfigurieren Sie Ihre 3-Teiler Felgenverbreiterungs-Specs. Berechnen Sie Inner Barrel und Outer Lip Größen, neue ET-Einpresstiefe, und speichern Sie Ihre Konfigurationen.', es: 'Configure las especificaciones de ensanchamiento de sus llantas de 3 piezas. Calcule tamaños de barrel interior y labio exterior, nuevo ET, y guarde sus configuraciones.', fr: 'Configurez les spécifications d\'élargissement de vos jantes 3 pièces. Calculez les tailles de barrel intérieur et lèvre extérieure, le nouvel ET, et sauvegardez vos configurations.', pl: 'Skonfiguruj specyfikacje poszerzania felg 3-częściowych. Oblicz rozmiary beczki wewnętrznej i obręczy zewnętrznej, nowy offset ET i zapisz konfiguracje.' },
  'home.openSpecCalc': { en: 'Open Spec Calc', nl: 'Spec Calculator openen', de: 'Spec-Rechner öffnen', es: 'Abrir Calculadora Spec', fr: 'Ouvrir le Calculateur Spec', pl: 'Otwórz Kalkulator Spec' },
  'home.needSomethingSpecial': { en: 'NEED SOMETHING SPECIAL?', nl: 'IETS SPECIAALS NODIG?', de: 'ETWAS BESONDERES GESUCHT?', es: '¿NECESITA ALGO ESPECIAL?', fr: 'BESOIN DE QUELQUE CHOSE DE SPÉCIAL ?', pl: 'SZUKASZ CZEGOŚ SPECJALNEGO?' },
  'home.specialDesc': { en: 'We specialize in sourcing hard-to-find wheels directly from Japan. Let us know what you\'re looking for.', nl: 'Wij zijn gespecialiseerd in het leveren van moeilijk te vinden velgen, rechtstreeks uit Japan. Laat ons weten wat u zoekt.', de: 'Wir sind spezialisiert auf die Beschaffung schwer erhältlicher Felgen direkt aus Japan. Teilen Sie uns mit, wonach Sie suchen.', es: 'Nos especializamos en la obtención de llantas difíciles de encontrar directamente desde Japón. Cuéntenos qué busca.', fr: 'Nous sommes spécialisés dans l\'approvisionnement de jantes rares directement depuis le Japon. Dites-nous ce que vous recherchez.', pl: 'Specjalizujemy się w pozyskiwaniu trudno dostępnych felg bezpośrednio z Japonii. Daj nam znać, czego szukasz.' },
  'home.requestCustomWheels': { en: 'Request Custom Wheels', nl: 'Custom Velgen Aanvragen', de: 'Sonderfelgen anfragen', es: 'Solicitar Llantas Personalizadas', fr: 'Demander des Jantes Sur Mesure', pl: 'Zamów Felgi Na Miarę' },

