  // ─── AuthenticityBlock ───
  'auth.title': { en: 'How We Verify Authenticity', nl: 'Hoe Wij Authenticiteit Verifiëren', de: 'Wie Wir Authentizität Überprüfen', es: 'Cómo Verificamos la Autenticidad', fr: 'Comment Nous Vérifions l\'Authenticité', pl: 'Jak Weryfikujemy Autentyczność' },
  'auth.statement': { en: 'We focus exclusively on authentic heritage wheels — never replicas.', nl: 'Wij richten ons uitsluitend op authentieke heritage velgen — nooit replica\'s.', de: 'Wir konzentrieren uns ausschließlich auf authentische Heritage-Felgen — niemals Repliken.', es: 'Nos enfocamos exclusivamente en llantas heritage auténticas — nunca réplicas.', fr: 'Nous nous concentrons exclusivement sur les jantes heritage authentiques — jamais de répliques.', pl: 'Skupiamy się wyłącznie na oryginalnych felgach heritage — nigdy replikach.' },
  'auth.heatstamp': { en: 'Heatstamp & Markings', nl: 'Heatstamp & Markeringen', de: 'Heatstamp & Markierungen', es: 'Estampado y Marcas', fr: 'Estampage & Marquages', pl: 'Stemple i Oznaczenia' },
  'auth.heatstampDesc': { en: 'Every wheel is checked for factory heatstamps, casting marks, and brand identifiers.', nl: 'Elke velg wordt gecontroleerd op fabrieksstempels, gietmerken en merkidentificaties.', de: 'Jede Felge wird auf Werks-Heatstamps, Gussmarken und Markenkennzeichnungen geprüft.', es: 'Cada llanta se inspecciona en busca de estampados de fábrica, marcas de fundición e identificadores de marca.', fr: 'Chaque jante est vérifiée pour les estampages d\'usine, les marques de coulée et les identifiants de marque.', pl: 'Każda felga jest sprawdzana pod kątem fabrycznych stempli, znaków odlewniczych i identyfikatorów marki.' },
  'auth.forgedCast': { en: 'Forged / Cast ID', nl: 'Gesmeed / Gegoten ID', de: 'Geschmiedet / Gegossen ID', es: 'ID Forjado / Fundido', fr: 'ID Forgé / Coulé', pl: 'ID Kute / Odlewane' },
  'auth.forgedCastDesc': { en: 'We identify the manufacturing method — forged, cast, or flow-formed — to confirm authenticity.', nl: 'Wij identificeren de productiemethode — gesmeed, gegoten of flow-formed — om authenticiteit te bevestigen.', de: 'Wir identifizieren die Herstellungsmethode — geschmiedet, gegossen oder flow-formed — um die Authentizität zu bestätigen.', es: 'Identificamos el método de fabricación — forjado, fundido o flow-formed — para confirmar la autenticidad.', fr: 'Nous identifions la méthode de fabrication — forgé, coulé ou flow-formed — pour confirmer l\'authenticité.', pl: 'Identyfikujemy metodę produkcji — kute, odlewane lub flow-formed — aby potwierdzić autentyczność.' },
  'auth.serialNumber': { en: 'Serial Number Checks', nl: 'Serienummer Controles', de: 'Seriennummer-Prüfungen', es: 'Verificación de Números de Serie', fr: 'Vérification des Numéros de Série', pl: 'Weryfikacja Numeru Seryjnego' },
  'auth.serialNumberDesc': { en: 'Serial and lot numbers are verified against known manufacturer databases.', nl: 'Serie- en lotnummers worden geverifieerd aan de hand van bekende fabrikantendatabases.', de: 'Serien- und Losnummern werden anhand bekannter Herstellerdatenbanken überprüft.', es: 'Los números de serie y lote se verifican contra bases de datos conocidas del fabricante.', fr: 'Les numéros de série et de lot sont vérifiés dans les bases de données des fabricants.', pl: 'Numery seryjne i partie są weryfikowane w znanych bazach danych producentów.' },
  'auth.condition': { en: 'Condition Inspection', nl: 'Conditie-inspectie', de: 'Zustandsinspektion', es: 'Inspección de Condición', fr: 'Inspection de l\'État', pl: 'Inspekcja Stanu' },
  'auth.conditionDesc': { en: 'Full inspection for cracks, bends, corrosion, and structural integrity.', nl: 'Volledige inspectie op scheuren, buigingen, corrosie en structurele integriteit.', de: 'Vollständige Inspektion auf Risse, Verformungen, Korrosion und strukturelle Integrität.', es: 'Inspección completa de grietas, dobleces, corrosión e integridad estructural.', fr: 'Inspection complète des fissures, déformations, corrosion et intégrité structurelle.', pl: 'Pełna inspekcja pod kątem pęknięć, wygięć, korozji i integralności strukturalnej.' },
