  'authenticity.compHeatstampOriginal': { en: 'Deep, precise factory stamp', nl: 'Diepe, precieze fabrieksstempel', de: 'Tiefer, präziser Werksstempel', es: 'Estampado de fábrica profundo y preciso', fr: 'Estampage d\'usine profond et précis', pl: 'Głęboki, precyzyjny stempel fabryczny' },
  'authenticity.compHeatstampReplica': { en: 'Shallow or missing stamp', nl: 'Ondiepe of ontbrekende stempel', de: 'Flacher oder fehlender Stempel', es: 'Estampado superficial o ausente', fr: 'Estampage superficiel ou absent', pl: 'Płytki lub brakujący stempel' },
