  'soldArchive.heroSubtitle': { en: 'A selection of authentic JDM wheel sets we\'ve sourced and delivered to customers worldwide.', nl: 'Een selectie authentieke JDM-velgensets die we hebben gevonden en aan klanten wereldwijd hebben geleverd.', de: 'Eine Auswahl authentischer JDM-Felgensätze, die wir beschafft und weltweit an Kunden geliefert haben.', es: 'Una selección de juegos de llantas JDM auténticas que hemos obtenido y entregado a clientes en todo el mundo.', fr: 'Une sélection de jeux de jantes JDM authentiques que nous avons sourcés et livrés à des clients du monde entier.' },
  'soldArchive.photoPlaceholder': { en: 'Wheel Photo', nl: 'Velgfoto', de: 'Felgenfoto', es: 'Foto de Llanta', fr: 'Photo de Jante' },
  'soldArchive.sold': { en: 'SOLD', nl: 'VERKOCHT', de: 'VERKAUFT', es: 'VENDIDO', fr: 'VENDU' },
