  'spacer.warning20mm': { en: 'For 20 mm spacers, please verify that the length of the central hub lip is no longer than 17 mm.', nl: 'Controleer bij 20 mm spacers of de centrale naaflippen niet langer zijn dan 17 mm.', de: 'Bei 20 mm Spurverbreiterungen prüfen Sie, ob die zentrale Nabenlippe nicht länger als 17 mm ist.', es: 'Para espaciadores de 20 mm, verifique que el labio central del buje no sea mayor a 17 mm.', fr: 'Pour les entretoises de 20 mm, vérifiez que la lèvre du moyeu ne dépasse pas 17 mm.', pl: 'Przy dystansach 20 mm sprawdź, czy kołnierz centrujący piasty nie przekracza 17 mm.' },
  'spacer.warningCustom': { en: 'These spacers are custom made to your specification. Once the order is placed it cannot be cancelled. Delivery times can be up to 15 days.', nl: 'Deze spacers worden op maat gemaakt. Na bestelling kan de order niet worden geannuleerd. Levertijd tot 15 dagen.', de: 'Diese Spurverbreiterungen werden nach Ihren Angaben gefertigt. Nach Bestellung ist keine Stornierung möglich. Lieferzeit bis zu 15 Tage.', es: 'Estos espaciadores se fabrican a medida. Una vez realizado el pedido no se puede cancelar. Plazo de entrega hasta 15 días.', fr: 'Ces entretoises sont fabriquées sur mesure. Une fois la commande passée, elle ne peut être annulée. Délai de livraison jusqu\'à 15 jours.', pl: 'Dystanse wykonywane na zamówienie według specyfikacji. Po złożeniu zamówienia nie można go anulować. Czas dostawy do 15 dni.' },

