  'nav.stanceParts': { en: 'StanceParts — Air Cup', nl: 'StanceParts — Air Cup', de: 'StanceParts — Air Cup', es: 'StanceParts — Air Cup', fr: 'StanceParts — Air Cup', pl: 'StanceParts — Air Cup' },
  'stanceparts.officialRetailerBadge': { en: 'Official Retailer', nl: 'Officieel Retailer', de: 'Offizieller Händler', es: 'Distribuidor Oficial', fr: 'Revendeur Officiel', pl: 'Oficjalny Sprzedawca' },
  'stanceparts.heroTitle': { en: 'StanceParts Air Cup', nl: 'StanceParts Air Cup', de: 'StanceParts Air Cup', es: 'StanceParts Air Cup', fr: 'StanceParts Air Cup', pl: 'StanceParts Air Cup' },
  'stanceparts.heroTitleAccent': { en: 'Lift System', nl: 'Lift Systeem', de: 'Lift-System', es: 'Sistema de Elevación', fr: 'Système de Levée', pl: 'System Podnoszenia' },
  'stanceparts.heroDesc': { en: 'Stay slammed on the street, raise up to 50mm whenever you need to. The Air Cup installs on your existing coilover in minutes — no permanent mods, no compromises.', nl: 'Blijf laag op straat, til je auto tot 50 mm op wanneer nodig. De Air Cup monteert in minuten op je bestaande coilover — geen permanente aanpassingen, geen compromissen.', de: 'Bleiben Sie auf der Straße flach, heben Sie das Fahrzeug bei Bedarf bis zu 50 mm an. Der Air Cup lässt sich in Minuten auf Ihrem Coilover montieren — keine dauerhaften Umbauten, keine Kompromisse.', es: 'Mantén tu coche bajo en la calle, levántalo hasta 50 mm cuando lo necesites. El Air Cup se instala en tu coilover en minutos — sin modificaciones permanentes, sin compromisos.', fr: 'Restez abaissé dans la rue, relevez jusqu\'à 50 mm quand vous en avez besoin. L\'Air Cup s\'installe sur votre combiné fileté en minutes — sans modifications permanentes, sans compromis.', pl: 'Jedź nisko po mieście, unieś auto do 50 mm kiedy potrzebujesz. Air Cup montuje się na istniejącym coiloverze w kilka minut — bez trwałych modyfikacji, bez kompromisów.' },
  'stanceparts.askWhatsApp': { en: 'Ask via WhatsApp', nl: 'Vraag via WhatsApp', de: 'Fragen per WhatsApp', es: 'Preguntar por WhatsApp', fr: 'Demander par WhatsApp', pl: 'Zapytaj przez WhatsApp' },
