  // ─── BC Racing ───
  'bcracing.officialDealerBadge': { en: 'Official Dealer', nl: 'Officieel Dealer', de: 'Offizieller Händler', es: 'Distribuidor Oficial', fr: 'Distributeur Officiel' },
  'bcracing.heroTitle': { en: 'BC Racing Coilovers', nl: 'BC Racing Coilovers', de: 'BC Racing Gewindefahrwerke', es: 'BC Racing Coilovers', fr: 'BC Racing Combinés Filetés' },
  'bcracing.heroTitleAccent': { en: 'Built Different', nl: 'Anders Gebouwd', de: 'Anders Gebaut', es: 'Construidos Diferente', fr: 'Construits Différemment' },
  'bcracing.heroDesc': { en: 'BC Racing coilovers — fully adjustable, competition-proven, and available in custom spring rates. Official dealer in the Netherlands.', nl: 'BC Racing coilovers — volledig verstelbaar, competitie-bewezen en beschikbaar in aangepaste veerrates. Officieel dealer in Nederland.', de: 'BC Racing Gewindefahrwerke — vollständig einstellbar, im Rennsport bewährt und in individuellen Federraten erhältlich. Offizieller Händler in den Niederlanden.', es: 'Coilovers BC Racing — totalmente ajustables, probados en competición y disponibles en tasas de muelle personalizadas. Distribuidor oficial en los Países Bajos.', fr: "Combinés filetés BC Racing — entièrement réglables, éprouvés en compétition et disponibles en taux de ressort personnalisés. Distributeur officiel aux Pays-Bas." },
  'bcracing.shopRangeLabel': { en: 'BC Racing collection', nl: 'BC Racing collectie', de: 'BC Racing Kollektion', es: 'Colección BC Racing', fr: 'Collection BC Racing' },
  'bcracing.shopRangeTitle': { en: 'Shop the Range', nl: 'Shop het Assortiment', de: 'Sortiment Entdecken', es: 'Ver la Gama', fr: 'Découvrir la Gamme' },
  'bcracing.productsEmpty': { en: 'Products loading soon', nl: 'Producten laden binnenkort', de: 'Produkte demnächst verfügbar', es: 'Productos disponibles pronto', fr: 'Produits bientôt disponibles' },
  'bcracing.productsEmptyNote': { en: 'Contact us via WhatsApp to order or ask about availability.', nl: 'Neem contact op via WhatsApp voor bestellingen of beschikbaarheid.', de: 'Kontaktieren Sie uns per WhatsApp für Bestellungen oder Verfügbarkeitsanfragen.', es: 'Contáctanos por WhatsApp para pedir o preguntar sobre disponibilidad.', fr: 'Contactez-nous par WhatsApp pour commander ou demander la disponibilité.' },
  'bcracing.card1Title': { en: 'Fast Shipping', nl: 'Snelle Verzending', de: 'Schneller Versand', es: 'Envío Rápido', fr: 'Livraison Rapide' },
  'bcracing.card1Desc': { en: 'Orders ship quickly across Europe. Stock kits go out fast, custom orders take a few weeks.', nl: 'Bestellingen worden snel door Europa verzonden. Voorraadkits gaan snel, maatwerk duurt een paar weken.', de: 'Bestellungen werden schnell durch Europa versandt. Lagerkits gehen sofort raus, individuelle Bestellungen dauern etwas länger.', es: 'Los pedidos se envían rápidamente por Europa. Los kits en stock salen pronto, los personalizados tardan unas semanas.', fr: 'Les commandes sont expédiées rapidement en Europe. Les kits en stock partent vite, les commandes sur mesure prennent quelques semaines.' },
  'bcracing.card2Title': { en: 'Save Your Serial Number', nl: 'Bewaar Je Serienummer', de: 'Seriennummer Aufbewahren', es: 'Guarda Tu Número de Serie', fr: 'Conservez Votre Numéro de Série' },
  'bcracing.card2Desc': { en: 'The serial number on your warranty card is essential for warranty claims and future support. Keep it safe.', nl: 'Het serienummer op de garantiekaart is essentieel voor garantieclaims en toekomstige support. Bewaar het goed.', de: 'Die Seriennummer auf der Garantiekarte ist für Garantieansprüche und zukünftigen Support unerlässlich. Aufbewahren.', es: 'El número de serie en tu tarjeta de garantía es esencial para reclamaciones y soporte futuro. Guárdalo.', fr: "Le numéro de série sur votre carte de garantie est essentiel pour les réclamations et le support futur. Conservez-le." },
  'bcracing.card3Title': { en: 'Custom Spring Rates', nl: 'Aangepaste Veerrates', de: 'Individuelle Federraten', es: 'Tasas de Muelle Personalizadas', fr: 'Taux de Ressort Personnalisés' },
  'bcracing.card3Desc': { en: 'Extra-low options and custom spring rates are available on request — just ask us what you need.', nl: 'Extra-lage opties en aangepaste veerrates zijn op aanvraag beschikbaar — vraag ons wat je nodig hebt.', de: 'Extraniedrige Optionen und individuelle Federraten sind auf Anfrage erhältlich — fragen Sie uns einfach.', es: 'Las opciones extra bajas y las tasas de muelle personalizadas están disponibles bajo pedido — solo pregúntanos.', fr: "Les options extra-basses et les taux de ressort personnalisés sont disponibles sur demande — demandez-nous." },
  'bcracing.card4Title': { en: 'Lead Time', nl: 'Levertijd', de: 'Lieferzeit', es: 'Plazo de Entrega', fr: 'Délai de Livraison' },
  'bcracing.card4Desc': { en: 'Custom/special-order kits take 3–4 weeks. Stock kits are typically available faster — contact us for current availability.', nl: 'Custom/speciale bestellingen nemen 3–4 weken. Voorraadkits zijn doorgaans sneller beschikbaar — neem contact op voor actuele beschikbaarheid.', de: 'Custom/Sonderbestellungen dauern 3–4 Wochen. Lagerkits sind in der Regel schneller verfügbar — kontaktieren Sie uns für die aktuelle Verfügbarkeit.', es: 'Los kits personalizados/de pedido especial tardan 3–4 semanas. Los kits en stock suelen estar disponibles más rápido — contacta para disponibilidad actual.', fr: "Les kits personnalisés/commandes spéciales prennent 3 à 4 semaines. Les kits en stock sont généralement disponibles plus rapidement — contactez-nous pour la disponibilité actuelle." },
  'bcracing.orderingTitle': { en: 'How to Order', nl: 'Hoe te Bestellen', de: 'So Bestellen Sie', es: 'Cómo Pedir', fr: 'Comment Commander' },
  'bcracing.orderingDesc': { en: 'Reach us at the email below or via WhatsApp and we will handle the rest.', nl: 'Neem contact op via het onderstaande e-mailadres of via WhatsApp en wij regelen de rest.', de: 'Kontaktieren Sie uns per E-Mail unten oder via WhatsApp und wir kümmern uns um den Rest.', es: 'Contáctanos en el correo de abajo o por WhatsApp y nosotros nos encargamos del resto.', fr: "Contactez-nous à l'adresse e-mail ci-dessous ou via WhatsApp et nous nous occupons du reste." },
  'bcracing.tradeDiscountNote': { en: '20% trade discount applies to spare parts and springs too.', nl: '20% handelskorting geldt ook voor reserveonderdelen en veren.', de: '20% Händlerrabatt gilt auch für Ersatzteile und Federn.', es: 'El descuento comercial del 20% también se aplica a piezas de repuesto y muelles.', fr: 'La remise professionnelle de 20 % s\'applique également aux pièces détachées et aux ressorts.' },
  'bcracing.askWhatsApp': { en: 'Ask via WhatsApp', nl: 'Vraag via WhatsApp', de: 'Fragen per WhatsApp', es: 'Preguntar por WhatsApp', fr: 'Demander par WhatsApp' },
